-- HKR Tournaments V3 database. Run this entire file in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text not null default 'Player', role text not null default 'player' check (role in ('player','admin')), created_at timestamptz not null default now());
create table if not exists public.app_settings (id integer primary key default 1 check (id=1), app_name text not null default 'HKR Tournaments', upi_id text not null default '', upi_name text not null default 'HKR Tournaments', qr_url text not null default '', support text not null default 'Contact admin', updated_at timestamptz not null default now());
insert into public.app_settings(id) values(1) on conflict(id) do nothing;
create table if not exists public.tournaments (id uuid primary key default gen_random_uuid(), title text not null, description text default '', mode text default 'Squad', map_name text default 'Bermuda', entry_fee numeric(12,2) not null default 0, prize_pool numeric(12,2) not null default 0, slots integer not null default 48, start_at timestamptz not null, room_id text default '', room_password text default '', status text not null default 'open', published boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.registrations (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, ff_uid text not null, ign text not null, status text not null default 'pending', created_at timestamptz not null default now(), unique(tournament_id,user_id));
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), registration_id uuid not null references public.registrations(id) on delete cascade, tournament_id uuid not null references public.tournaments(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, amount numeric(12,2) not null default 0, utr text not null, status text not null default 'pending', reviewed_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.wallet_transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, amount numeric(12,2) not null, note text default '', created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,name) values(new.id,coalesce(new.raw_user_meta_data->>'name','Player')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
alter table public.profiles enable row level security; alter table public.app_settings enable row level security; alter table public.tournaments enable row level security; alter table public.registrations enable row level security; alter table public.payments enable row level security; alter table public.wallet_transactions enable row level security;
drop policy if exists profiles_self on public.profiles; create policy profiles_self on public.profiles for select using(auth.uid()=id or public.is_admin());
drop policy if exists profiles_update_self on public.profiles; create policy profiles_update_self on public.profiles for update using(auth.uid()=id or public.is_admin()) with check(auth.uid()=id or public.is_admin());
drop policy if exists settings_read on public.app_settings; create policy settings_read on public.app_settings for select using(true); drop policy if exists settings_admin on public.app_settings; create policy settings_admin on public.app_settings for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists tournaments_public_read on public.tournaments; create policy tournaments_public_read on public.tournaments for select using(published=true or public.is_admin()); drop policy if exists tournaments_admin_write on public.tournaments; create policy tournaments_admin_write on public.tournaments for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists registrations_self_insert on public.registrations; create policy registrations_self_insert on public.registrations for insert with check(auth.uid()=user_id); drop policy if exists registrations_self_read on public.registrations; create policy registrations_self_read on public.registrations for select using(auth.uid()=user_id or public.is_admin()); drop policy if exists registrations_admin_update on public.registrations; create policy registrations_admin_update on public.registrations for update using(public.is_admin()) with check(public.is_admin()); drop policy if exists registrations_self_delete on public.registrations; create policy registrations_self_delete on public.registrations for delete using(auth.uid()=user_id or public.is_admin());
drop policy if exists payments_self_insert on public.payments; create policy payments_self_insert on public.payments for insert with check(auth.uid()=user_id); drop policy if exists payments_self_read on public.payments; create policy payments_self_read on public.payments for select using(auth.uid()=user_id or public.is_admin()); drop policy if exists payments_admin_update on public.payments; create policy payments_admin_update on public.payments for update using(public.is_admin()) with check(public.is_admin());
drop policy if exists wallet_self_read on public.wallet_transactions; create policy wallet_self_read on public.wallet_transactions for select using(auth.uid()=user_id or public.is_admin()); drop policy if exists wallet_admin_write on public.wallet_transactions; create policy wallet_admin_write on public.wallet_transactions for all using(public.is_admin()) with check(public.is_admin());
-- Admin bootstrap: after creating your account, run: update public.profiles set role='admin' where id=(select id from auth.users where email='YOUR_ADMIN_EMAIL');
